 1→#!/usr/bin/env node
 2→// Lab Platform — Launcher
 3→// Grid UI for managing lab instances. Start, stop, open, create.
 4→
 5→const http = require('node:http');
 6→const fs = require('node:fs');
 7→const path = require('node:path');
 8→const { spawn } = require('node:child_process');
 9→const { randomUUID } = require('node:crypto');
10→
11→const PLATFORM_DIR = __dirname;
12→const INSTANCES_DIR = path.join(PLATFORM_DIR, 'instances');
13→const GENESIS_DIR = process.env.GENESIS_DIR || path.resolve(PLATFORM_DIR, '..', 'genesis');
14→const CORE_SERVER = path.join(GENESIS_DIR, 'template', 'core', 'server.js');
15→const GLOBAL_PLUGINS_DIR = path.join(GENESIS_DIR, 'template', 'plugins');
16→const GLOBAL_SKILLS_DIR = path.join(GENESIS_DIR, 'template', 'skills');
17→const SERVER_ROOT = path.resolve(PLATFORM_DIR, '..');
18→let PORT_BASE = 9000;
19→try { PORT_BASE = JSON.parse(fs.readFileSync(path.join(SERVER_ROOT, 'server.json'), 'utf8')).portBase || 9000; } catch (e) {}
20→const PORT = PORT_BASE + 200;
21→
22→// Ensure instances directory exists
23→try { fs.mkdirSync(INSTANCES_DIR, { recursive: true }); } catch (e) {}
24→
25→// Track running instances
26→const running = {}; // id -> { proc, port }
27→
28→function getInstances() {
29→  const instances = [];
30→  try {
31→    for (const name of fs.readdirSync(INSTANCES_DIR)) {
32→      const dir = path.join(INSTANCES_DIR, name);
33→      const configPath = path.join(dir, 'lab.json');
34→      if (!fs.statSync(dir).isDirectory()) continue;
35→      if (!fs.existsSync(configPath)) continue;
36→      try {
37→        const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
38→        const hasFrontend = fs.existsSync(path.join(dir, 'frontend', 'server.js'));
39→        instances.push({
40→          id: name,
41→          name: config.name || name,
42→          description: config.description || '',
43→          icon: config.icon || '\u2697',
44→          color: config.color || '#888',
45→          port: config.port || (PORT_BASE + 210),
46→          frontendPort: (config.port || (PORT_BASE + 210)) + 70,
47→          model: config.model || 'opus',
48→          running: !!running[name],
49→          hasFrontend,
50→        });
51→      } catch (e) {}
52→    }
53→  } catch (e) {}
54→  return instances;
55→}
56→
57→function startInstance(id) {
58→  if (running[id]) return { port: running[id].port, already: true };
59→  const dir = path.join(INSTANCES_DIR, id);
60→  const configPath = path.join(dir, 'lab.json');
61→  if (!fs.existsSync(configPath)) return null;
62→  const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
63→  const port = config.port || (PORT_BASE + 210);
64→
65→  const proc = spawn('node', [CORE_SERVER], {
66→    cwd: dir,
67→    env: { ...process.env, LAB_INSTANCE: dir, LAB_PORT: String(port), GENESIS_DIR, GLOBAL_PLUGINS_DIR, GLOBAL_SKILLS_DIR },
68→    stdio: ['ignore', 'pipe', 'pipe'],
69→  });
70→  proc.stdout.on('data', d => process.stdout.write(`[${id}] ${d}`));
71→  proc.stderr.on('data', d => process.stderr.write(`[${id}] ${d}`));
72→  proc.on('close', () => { delete running[id]; });
73→  running[id] = { proc, port, frontendProc: null, frontendPort: null };
74→
75→  // Start frontend if it exists
76→  const frontendServer = path.join(dir, 'frontend', 'server.js');
77→  const frontendPort = port + 70;
78→  if (fs.existsSync(frontendServer)) {
79→    const fProc = spawn('node', [frontendServer], {
80→      cwd: dir,
81→      env: { ...process.env, PORT: String(frontendPort) },
82→      stdio: ['ignore', 'pipe', 'pipe'],
83→    });
84→    fProc.stdout.on('data', d => process.stdout.write(`[${id}-fe] ${d}`));
85→    fProc.s

