 1→#!/usr/bin/env node
 2→// Frontend Dev Server — serves static files + proxies to lab API
 3→const http = require('node:http');
 4→const fs = require('node:fs');
 5→const path = require('node:path');
 6→
 7→const FRONTEND_DIR = __dirname;
 8→const PUBLIC_DIR = path.join(FRONTEND_DIR, 'public');
 9→const PORT = parseInt(process.env.PORT || 3280);
10→
11→let LAB_PORT = 3210;
12→try {
13→  const labConfig = JSON.parse(fs.readFileSync(path.join(FRONTEND_DIR, '..', 'lab.json'), 'utf8'));
14→  LAB_PORT = labConfig.port || 3210;
15→} catch (e) {}
16→
17→let THEME = { name: 'default', primary: '#c8a55a', bg: '#0a0b10', text: '#e4e4ec' };
18→try {
19→  THEME = { ...THEME, ...JSON.parse(fs.readFileSync(path.join(FRONTEND_DIR, 'theme', 'theme.json'), 'utf8')) };
20→} catch (e) {}
21→
22→const MIME = {
23→  '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript',
24→  '.json': 'application/json', '.svg': 'image/svg+xml', '.png': 'image/png',
25→  '.xml': 'application/xml', '.txt': 'text/plain', '.ico': 'image/x-icon',
26→  '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp',
27→  '.woff2': 'font/woff2', '.woff': 'font/woff',
28→};
29→
30→function serveFile(res, filePath) {
31→  const ext = path.extname(filePath);
32→  const mime = MIME[ext] || 'application/octet-stream';
33→  try {
34→    const content = fs.readFileSync(filePath);
35→    res.writeHead(200, { 'Content-Type': mime + (['.html','.css','.js'].includes(ext) ? '; charset=utf-8' : '') });
36→    res.end(content);
37→  } catch (e) { res.writeHead(404); res.end('Not found'); }
38→}
39→
40→function proxyToLab(req, res) {
41→  const opts = { hostname: '127.0.0.1', port: LAB_PORT, path: req.url, method: req.method, headers: { ...req.headers, host: `127.0.0.1:${LAB_PORT}` } };
42→  const proxy = http.request(opts, labRes => { res.writeHead(labRes.statusCode, labRes.headers); labRes.pipe(res); });
43→  proxy.on('error', () => { res.writeHead(502); res.end('Lab backend not available'); });
44→  req.pipe(proxy);
45→}
46→
47→const server = http.createServer((req, res) => {
48→  const url = new URL(req.url, `http://localhost:${PORT}`);
49→  if (url.pathname.startsWith('/api/')) { proxyToLab(req, res); return; }
50→
51→  // Resolve file path with clean URL support
52→  let filePath;
53→  const pathname = url.pathname.replace(/\/+$/, '') || '/';
54→
55→  if (pathname === '/') {
56→    filePath = path.join(PUBLIC_DIR, 'index.html');
57→  } else {
58→    // Try exact file first
59→    filePath = path.join(PUBLIC_DIR, pathname);
60→    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
61→      // Try pathname.html
62→      const htmlPath = path.join(PUBLIC_DIR, pathname + '.html');
63→      if (fs.existsSync(htmlPath) && fs.statSync(htmlPath).isFile()) {
64→        filePath = htmlPath;
65→      } else {
66→        // Try pathname/index.html (directory-based routing)
67→        const dirIndex = path.join(PUBLIC_DIR, pathname, 'index.html');
68→        if (fs.existsSync(dirIndex) && fs.statSync(dirIndex).isFile()) {
69→          filePath = dirIndex;
70→        } else {
71→          // 404 fallback
72→          filePath = path.join(PUBLIC_DIR, '404.html');
73→          if (!fs.existsSync(filePath)) filePath = path.join(PUBLIC_DIR, 'index.html');
74→        }
75→      }
76→    }
77→  }
78→
79→  serveFile(res, filePath);
80→});
81→
82→server.listen(PORT, () => {
83→  console.log(`  Frontend: http://localhost:${PORT}`);
84→  console.log(`  Backend:  http://localhost:${LAB_PORT}`);
85→});
86→

